.xt-text-pt::after { content: "社区动态"; position: absolute; top: 15px; left: 15px; font-size: 16px; font-weight: bold; color: #0f0f0f; }
.xt-text-pt::before { content: "刚刚发布"; position: absolute; top: 38px; left: 15px; font-size: 12px; color: #606060; }

