}
.xt-text-chatTitle::after {
    content: "";
    position: absolute; right: 10px; top: 7px;
    width: 18px; height: 18px;
    background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23555555%22%20stroke-width%3D%221%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Ccircle%20cx%3D%225%22%20cy%3D%2212%22%20r%3D%221.7%22%20fill%3D%22%23555555%22%2F%3E%3Ccircle%20cx%3D%2212%22%20cy%3D%2212%22%20r%3D%221.7%22%20fill%3D%22%23555555%22%2F%3E%3Ccircle%20cx%3D%2219%22%20cy%3D%2212%22%20r%3D%221.7%22%20fill%3D%22%23555555%22%2F%3E%3C%2Fsvg%3E") center / contain no-repeat;
}
.xt-text-chatTitle:empty { display: none !important; }
.xt-bubbles { border-top: none; border-radius: 0 0 4px 4px; }

/* 气泡：微信形状（小圆角 + 顶部侧边小三角），配色沿用原来的 */
.xt-bubble-left .xt-bubble-body, .xt-bubble-left.xt-bubble-body,
.xt-bubble-right .xt-bubble-body, .xt-bubble-right.xt-bubble-body {
    position: relative;
    padding: 8px 12px !important;
    font-size: 12px !important;
    line-height: 1.5 !important;
