}
.xt-bubble-right .xt-bubble-body, .xt-bubble-right.xt-bubble-body {
    background: linear-gradient(to bottom, #c9f59b, #8fd65a) !important;
    border: 1px solid #6fae3e !important;
    color: #1d3a0c !important;
    text-shadow: 0 1px 0 rgba(255,255,255,0.35);
}
/* 小三角：贴在气泡顶部侧边，像微信一样朝外 */
.xt-bubble-left .xt-bubble-body::after, .xt-bubble-left.xt-bubble-body::after {
    content: ""; position: absolute;
    top: 12px; left: -5px;
    width: 8px; height: 8px;
