    transform: rotate(45deg);
}
.xt-bubble-right .xt-bubble-body::after, .xt-bubble-right.xt-bubble-body::after {
    content: ""; position: absolute;
    top: 12px; right: -5px;
    width: 8px; height: 8px;
    background: #b2e67f;
    border-right: 1px solid #6fae3e;
    border-bottom: 1px solid #6fae3e;
    transform: rotate(-45deg);
}
.xt-bubble-body:empty { display: none !important; }

/* ======================================================================
   新增三块：推特帖子 / 韩系论坛 / 小剧场（用 :has() 区分各自的卡片；图标全部为 SVG）
