/* ---- 台词：说话人署名（S）+ 台词（L），无边框、左右错落 ---- */
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS1,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS2,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS3,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS4,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS5,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS6 {
    display: flex !important;
    align-items: center;
    gap: 7px;
    box-sizing: border-box;
    width: 80%;
    margin-top: 14px !important; margin-bottom: 0 !important;
    padding: 0 !important;
    background: none !important; border: 0 !important; box-shadow: none !important; border-radius: 0 !important;
    font-family: -apple-system, "PingFang SC", "Helvetica Neue", sans-serif !important;
    font-size: 11px !important; font-weight: 700 !important; font-style: normal !important;
    letter-spacing: 1.5px !important; line-height: 16px !important;
    color: #4f5a63 !important;
    text-shadow: none !important;
}
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS1::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS2::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS3::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS4::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS5::before,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS6::before {
    content: "";
    flex: none;
    width: 6px; height: 6px;
    border-radius: 50%;
    background: #4f5a63;
    box-shadow: 0 0 0 2px rgba(79,90,99,.16);
}
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS1::after,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS2::after,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS3::after,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS4::after,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS5::after,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS6::after {
    content: "";
    flex: 1;
    height: 1px;
    background: linear-gradient(to right, #c4c9cd, rgba(196,201,205,0));
}
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS1,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS3,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS5 { margin-left: 20px !important; margin-right: auto !important; }
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS2,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS4,
.xt-card:has(.xt-text-theaterTitle) .xt-text-theaterS6 {
    margin-left: auto !important; margin-right: 20px !important;
    flex-direction: row-reverse;
    text-align: right !important;
