    box-shadow: inset 0 1px 3px rgba(0,0,0,0.05) !important;
}
.xt-section:last-child .xt-section-body::before {
    content: "B    I    U    Aa    100%";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 24px; line-height: 24px;
    background: linear-gradient(to bottom, #f0f0f0, #e0e0e0);
    border-bottom: 1px solid #b5b5b5;
    font-size: 11px; font-weight: bold; color: #555;
    padding-left: 10px; word-spacing: 14px;
    border-radius: 4px 4px 0 0;
    text-shadow: 0 1px 0 rgba(255,255,255,0.7);
}

xinshengLayout:
# 顶部工具栏：名言滚动（样式里固定在 Menu 栏位置）
@marquee famousQuote

@spacer 8

@row 2
@card
  @image charImage
  @image userImage
@endcard

@card
  @text nickname
  @text signature
  @tags
    tag1
    tag2
    tag3
@endcard
@endrow

@spacer 16

@section DESCRIPTION
  description

@spacer 12

# 提问箱：用官方 @collapse 做成可点开的抽屉
@collapse "ANONYMOUS ASK BOX" 1
  @quote anonQuestion
  @text anonAnswer
@endcollapse

@spacer 12

# 聊天记录：左=Char，右=聊天对象（user以外的人），6个来回，不折叠
@card "CHAT LOG · 聊天记录"
  @text chatTitle
  @bubbles .stagger
    log1:left
    log2:right
    log3:left
    log4:right
    log5:left
    log6:right
    log7:left
    log8:right
    log9:left
    log10:right
    log11:left
    log12:right
@endcard

@spacer 12

