  @text theaterS1
  @text theaterL1
  @text theaterS2
  @text theaterL2
  @text theaterN2
  @text theaterS3
  @text theaterL3
  @text theaterS4
  @text theaterL4
  @text theaterN3
  @text theaterS5
  @text theaterL5
  @text theaterS6
  @text theaterL6
  @text theaterEnd
@endcard

@spacer 12

